import{_ as t,H as E,f as B,i}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"阶段复习（四） | 设计一个能做事Agent（内含技术小白也能读懂的LoRA微调过程）","description":"","frontmatter":{},"headers":[],"relativePath":"成为AGI产品经理/阶段复习（四）｜设计一个能做事Agent（内含技术小白也能读懂的LoRA微调过程）.md","filePath":"成为AGI产品经理/阶段复习（四）｜设计一个能做事Agent（内含技术小白也能读懂的LoRA微调过程）.md","lastUpdated":1795557342000}'),n={name:"成为AGI产品经理/阶段复习（四）｜设计一个能做事Agent（内含技术小白也能读懂的LoRA微调过程）.md"};function s(a,e,A,p,o,l){return E(),B("div",null,[...e[0]||(e[0]=[i('<h1 id="阶段复习-四-设计一个能做事agent-内含技术小白也能读懂的lora微调过程" tabindex="-1">阶段复习（四） | 设计一个能做事Agent（内含技术小白也能读懂的LoRA微调过程） <a class="header-anchor" href="#阶段复习-四-设计一个能做事agent-内含技术小白也能读懂的lora微调过程" aria-label="Permalink to &quot;阶段复习（四） | 设计一个能做事Agent（内含技术小白也能读懂的LoRA微调过程）&quot;">​</a></h1><p>你好，我是晓蕾。</p><p>终于来到了最后一个案例，今天我们复习一下怎么做一个“自助工单小助手”。和前面的 Chat类工作不同，这次我们会让 Agent 做 Act 类的工作。</p><p>想做好这个产品，首先我们要理解什么是“做事的 Agent”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/1.png" alt=""></a></p><p>过去几十年互联网的发展帮我们构建起了巨大的数字世界，它使人类与物理世界可以进行广泛链接。比如在某打车软件的 App 里，完成了出行工具、司机与乘客的链接；在某个购物 App里，完成了商品、卖家与买家的链接。</p><p>而 AI 带给我们的，就是把人类从数字世界中解放出来，让 Agent 代替人类完成这一链接。</p><p>（上面都是二姐说的，为了保证阅读连贯性，没用引用格式，特此声明～）</p><p>我们试着拆解一下这次的 Agent 案例。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/2.png" alt=""></a></p><p>梳理之后，我们发现一个 Agent 需要具备 3 个方面的能力。</p><ol><li><p>准确的意图识别、Query 重写和路由能力。</p></li><li><p>正确地思考。</p></li><li><p>正确地行动。</p></li></ol><p>其中，二姐特意讲了提升行动力的两种方式，我也放到这里，如果有需要可以保存。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/3.png" alt=""></a></p><p>话说回来，前面说的 3 个能力，我们已经掌握了“准确的意图识别、Query 重写和路由能力”，那如何正确地思考、正确地行动呢？答案是：微调。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/4.png" alt=""></a></p><p>听到这个技术名词，是不是觉得可以“休息一下”了？No！作为产品经理，我们在这一步还有很多事情要做。从明确微调数据特征，到准备数据，再到评估模型，都少不了咱们的身影。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/5.png" alt=""></a></p><p>最后，我们一起复习一下“千层饼抹酱”的生动比喻，理解 LoRA 微调的过程，让你和技术同学的沟通更加丝滑～</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/6.png" alt=""></a></p><p>好啦，以上就是这次案例的重点内容。老规矩，提醒下这个案例的几次作业。</p><ul><li>作业一</li></ul><p>下载蚂蚁金服的生活助手支小宝，让支小宝帮你做点“事”，测一测它执行得是否准确？对于执行较好的指令，想想它背后到底调用了什么样的接口？对于执行错误的指令，想想如何才能让它做得更好？</p><ul><li>作业二</li></ul><p>我们提到过，LoRA 中被训练的参数量大幅降低，那么到底降幅有多大呢？ 我们做一道加减乘除运算题来体会一下。</p><p>观察 Huggingface 上训练 Mistral 7B 的案例：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/%25E9%2598%25B6%25E6%25AE%25B5%25E5%25A4%258D%25E4%25B9%25A0%25EF%25BC%2588%25E5%259B%259B%25EF%25BC%2589/7.png" alt=""></a></p><p>在这个案例里，</p><ul><li><p>指定 Target Module 是 “embed_tokens”, “lm_head”, “q_proj”, “v_proj”，结合Mistral-7B这个模型的架构，这几层对应的参数矩阵大小分别是：32000 x 4096， 32000 x 4096，4096 x 4096，1024 x 4096。</p></li><li><p>指定 Rank=64。</p></li></ul><p>根据这些数值，计算 LoRA 微调总共需要的训练参数，看看和 Mistral 7B 的总共参数量7,273,849,000 相比，有多大幅度的降低呢？</p><ul><li>作业三</li></ul><p>体验一次数据准备的过程吧。使用你曾经遇到的一个工作流，你也可以使用我们在文中提到的工作流，借助 OpenAI 或者智谱等大语言模型完成从工作流到 few shots，再到 many shots 的过程。</p><p>到这里，咱们的四个案例就复习完毕了。明天会正式开启“商业化”章节的学习，我先列出几个问题：</p><ul><li><p>AGI 产品经理的 PRD 怎么写？</p></li><li><p>AI 技术将如何改变产品赚钱的方式？</p></li><li><p>那些算力成本、私有化部署成本到底怎么算？</p></li></ul><p>学到这里，这些问题你有头绪了吗？可以在留言区和大家分享分享。另外，关于专栏，如果你有什么建议或更好的想法，也欢迎分享在留言区，我一定会关注。如果觉得这门课有所帮助，也可以把课程分享给同事或朋友。</p><p>我们下节课见！</p>',36)])])}const h=t(n,[["render",s]]);export{g as __pageData,h as default};
